INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_drama_rooftop', NULL, 'Rooftop confession', 'drama', '{"nodes":[{"id":"cast","kind":"text","title":"Cast","params":{"text":"Two adult friends in their late twenties: Maya, curly dark hair, denim jacket; Leo, short hair, grey hoodie."},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"k1","kind":"image","title":"Keyframe 1","params":{"model":"bytedance/seedream-5.0-lite","prompt":"Cinematic film still: Wide shot of two friends sitting on a city rooftop at dusk, skyline lights coming on","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k2","kind":"image","title":"Keyframe 2","params":{"model":"bytedance/seedream-5.0-lite","prompt":"Cinematic film still: Close-up of Maya turning toward Leo, nervous smile","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k3","kind":"image","title":"Keyframe 3","params":{"model":"bytedance/seedream-5.0-lite","prompt":"Cinematic film still: Over-the-shoulder shot of Leo reacting, the city behind","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v1","kind":"video","title":"Shot 1","params":{"model":"bytedance/seedance-2.0-mini","prompt":"Slow push-in as the wind moves their hair","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v2","kind":"video","title":"Shot 2","params":{"model":"bytedance/seedance-2.0-mini","prompt":"Maya speaks quietly, Leo looks up","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v3","kind":"video","title":"Shot 3","params":{"model":"bytedance/seedance-2.0-mini","prompt":"Leo smiles, the camera drifts back","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"cast","port":"out"},"to":{"node":"k1","port":"prompt"}},{"id":"edge_t2","from":{"node":"cast","port":"out"},"to":{"node":"k2","port":"prompt"}},{"id":"edge_t3","from":{"node":"cast","port":"out"},"to":{"node":"k3","port":"prompt"}},{"id":"edge_t4","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t5","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}},{"id":"edge_t6","from":{"node":"k3","port":"out"},"to":{"node":"v3","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","k3","v1","v2","v3"]}]}', '[{"id":"cast","kind":"text","label":"Cast","param":"text","required":false,"default":"Two adult friends in their late twenties: Maya, curly dark hair, denim jacket; Leo, short hair, grey hoodie."}]', NULL, 0, 'Two friends on a city rooftop at dusk, and one finally says what they mean.', '{"durationSec":15,"ratio":"9:16","roles":0,"hasLines":false,"nodeCount":7,"tags":["3 shots","Vertical","15 seconds"]}', 0, 0)
