","prompt":"Priya stands slowly, the lights flicker","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"cast","port":"out"},"to":{"node":"k1","port":"prompt"}},{"id":"edge_t2","from":{"node":"cast","port":"out"},"to":{"node":"k2","port":"prompt"}},{"id":"edge_t3","from":{"node":"cast","port":"out"},"to":{"node":"k3","port":"prompt"}},{"id":"edge_t4","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t5","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}},{"id":"edge_t6","from":{"node":"k3","port":"out"},"to":{"node":"v3","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","k3","v1","v2","v3"]}]}', '[{"id":"cast","kind":"text","label":"Cast","param":"text","required":false,"default":"An adult office worker, Priya, glasses, navy blazer; the empty office is lit by desk lamps."}]', NULL, 0, 'A quiet late night at the office ends with a discovery nobody expected.', '{"durationSec":15,"ratio":"9:16","roles":0,"hasLines":false,"nodeCount":7,"tags":["3 shots","Vertical","15 seconds"]}', 0, 0)
